// ============================================================
// 정보보안 뉴스 필터링 + 근거기반 요약 프롬프트 (v5.2-grounded)
// 작성일: 2026-02-09
// 목표: EXAONE 7.8B 환각 최소화 (제목-only 제거, 원문 스니펫 강제, 구조화 출력)
// ============================================================

const rssArticles = $input.all() || [];

if (rssArticles.length === 0) {
  throw new Error('RSS 데이터가 없습니다. RSS 노드 연결을 확인하세요.');
}

// 응답 스키마 강제 사용 여부 (모델/게이트웨이가 미지원이면 false로 변경)
const USE_JSON_SCHEMA = true;

// 기사별 전달 텍스트 최대 길이 (너무 길면 소형 모델 환각/혼선 증가)
const MAX_CHARS_PER_ARTICLE = 1800;

// ============================================================
// 1. 키워드 가중치 정의 (한글/영어 통합)
// ============================================================
const keywordWeights = [
  ["랜섬웨어", 8], ["랜섬", 8], ["ransom", 8], ["ransomware", 8],
  ["제로데이", 8], ["0-day", 8], ["zero-day", 8], ["zeroday", 8],

  ["유출", 7], ["개인정보", 7], ["leak", 7], ["data breach", 7],
  ["피싱", 6], ["phish", 6], ["phishing", 6],
  ["공급망", 6], ["supply", 6], ["supply chain", 6],
  ["apt", 6], ["apt공격", 6], ["해킹", 6], ["hacking", 6],

  ["침해", 5], ["사이버 공격", 5], ["cyber attack", 5],
  ["악성코드", 5], ["malware", 5], ["바이러스", 5],
  ["취약점", 4], ["cve", 4], ["vulnerability", 4],
  ["계정", 4], ["자격증명", 4], ["credential", 4],
  ["ddos", 4], ["디도스", 4],

  ["사이버", 3], ["보안사고", 3], ["security", 3],
  ["패치", 3], ["업데이트", 3], ["patch", 3],
  ["클라우드", 2], ["cloud", 2],
  ["microsoft", 2], ["google", 2], ["apple", 2]
];

// ============================================================
// 2. 제외 키워드 (금융/투자/비보안 일반 뉴스 차단)
// ============================================================
const excludeKeywords = [
  '가격', '시세', '전망', '상승', '하락', '투자',
  '매수', '매도', '거래량', '시가총액', '주식', '증권',
  'etf', '비트코인', '코인', '순유출', '비중 감축',
  '달러 유출', '알트코인', '이더리움', '리플',
  '배당', '수익률', '포트폴리오', '자산운용', '토큰', 'nft 가격',
  '날씨', '기온', '강수', '태풍', '폭염', '한파',
  '축구', '야구', '농구', '배구', '골프', '올림픽', '월드컵', '스포츠',
  '연예', '가수', '배우', '드라마', '영화', '음악', '예능', '방송',
  '인수합병', 'm&a', '지분 인수', '투자 유치', '상장', 'ipo', '기업공개',
  '매출', '영업이익', '순이익', '실적', '분기 실적',
  '채용', '구인', '입사', '퇴사', '이직', '인사발령', '승진',
  '부동산', '아파트', '재개발', '분양', '자동차'
];

// ============================================================
// 3. 텍스트 정규화/추출 유틸
// ============================================================
function stripHtml(input) {
  return String(input || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeText(input) {
  return stripHtml(input)
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function clip(text, maxLen) {
  if (!text) return '';
  if (text.length <= maxLen) return text;
  return text.slice(0, maxLen) + ' ...[TRUNCATED]';
}

function getArticleSourceText(article) {
  const title = normalizeText(article.json.title || '');
  const desc = normalizeText(article.json.description || article.json.summary || '');
  const content = normalizeText(article.json.content || article.json['content:encoded'] || article.json.contentSnippet || '');

  // 중복 제거: content가 desc를 포함하면 content 우선
  let merged = '';
  if (content && desc && content.includes(desc)) {
    merged = content;
  } else {
    merged = [desc, content].filter(Boolean).join(' ');
  }

  return {
    title,
    sourceText: clip(merged, MAX_CHARS_PER_ARTICLE)
  };
}

// ============================================================
// 4. 마케팅/제품 콘텐츠 감지
// ============================================================
function isMarketingContent(article) {
  const title = normalizeText(article.json.title || '').toLowerCase();

  const marketingPatterns = [
    /솔루션\s*(출시|공개|선보|론칭)/,
    /제품\s*(출시|공개|선보|론칭)/,
    /신제품/,
    /스토리지.*출시/,
    /백업.*솔루션.*출시/,
    /(론칭|런칭|launching)/,
    /새로운\s*제품/,
    /출시.*예정/,

    /참가.*전시/,
    /개최.*컨퍼런스/,
    /전시회.*참가/,
    /공급\s*개시/,
    /라인업.*확대/,

    /\d+위\s*(선정|차지|달성|기록|올라)/,
    /(1|2|3|첫|톱|일)위.*선정/,
    /선정.*\d+위/,
    /랭킹.*\d+위/,
    /순위.*\d+위/,
    /(수상|선정|인정).*왕좌/,
    /\d+년\s*연속/,
    /top\s*\d+/i,
    /부문\s*\d+위/,
    /매체\s*선정/,
    /어워드.*수상/,
    /수상.*영예/,
    /대상.*수상/,
    /왕좌.*지켰다/,
    /최우수.*선정/,
    /연간.*랭킹/,
    /글로벌.*순위/
  ];

  const securityExceptions = [
    '취약점', '패치', '보안 업데이트', '공격', '해킹',
    '랜섬웨어', '악성코드', '유출', '침해', '피해',
    '사고', '공격 대상', '위협'
  ];

  if (securityExceptions.some(exc => title.includes(exc))) {
    return false;
  }

  return marketingPatterns.some(pattern => pattern.test(title));
}

// ============================================================
// 5. 키워드 점수 계산
// ============================================================
function calculateKeywordScore(article) {
  const { title, sourceText } = getArticleSourceText(article);
  const fullText = `${title} ${sourceText}`.toLowerCase();

  for (const keyword of excludeKeywords) {
    if (fullText.includes(keyword.toLowerCase())) {
      return { score: 0, keywords: ['제외: ' + keyword] };
    }
  }

  if (isMarketingContent(article)) {
    return { score: 0, keywords: ['제외: 제품홍보'] };
  }

  let score = 0;
  const matchedKeywords = [];
  const countedKeywords = new Set();

  for (const [keyword, weight] of keywordWeights) {
    const k = keyword.toLowerCase();
    if (countedKeywords.has(k)) continue;

    if (title.toLowerCase().includes(k)) {
      score += weight * 2;
      matchedKeywords.push(`${keyword}(제목×2)`);
      countedKeywords.add(k);
    } else if (fullText.includes(k)) {
      score += weight;
      matchedKeywords.push(keyword);
      countedKeywords.add(k);
    }
  }

  return { score, keywords: matchedKeywords };
}

// ============================================================
// 6. 전체 기사 점수 계산
// ============================================================
const articlesWithScore = rssArticles.map(art => {
  const result = calculateKeywordScore(art);
  const { title, sourceText } = getArticleSourceText(art);

  return {
    article: art,
    score: result.score,
    keywords: result.keywords,
    title,
    sourceText,
    pubDate: new Date(art.json.pubDate || art.json.isoDate || art.json.published || 0)
  };
});

const filteredArticles = articlesWithScore.filter(item => item.score > 0 && item.sourceText.length > 0);

console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
console.log(`📊 RSS 수집: ${rssArticles.length}개`);
console.log(`✅ 필터링 후: ${filteredArticles.length}개`);
console.log(`❌ 제외됨: ${rssArticles.length - filteredArticles.length}개`);
console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');

const excluded = articlesWithScore.filter(item => item.score === 0 || !item.sourceText);
if (excluded.length > 0) {
  console.log('\n🚫 제외된 기사 예시 (최대 3개):');
  excluded.slice(0, 3).forEach(item => {
    console.log(`   • ${item.article.json.title || '(제목없음)'}`);
    console.log(`     사유: ${item.sourceText ? item.keywords.join(', ') : '본문 없음'}`);
  });
}

if (filteredArticles.length === 0) {
  console.log('\n⚠️ 정보보안 관련 기사가 없습니다.');
  return [];
}

// ============================================================
// 7. 정렬 (점수 내림차순 → 날짜 최신순)
// ============================================================
const sortedArticles = filteredArticles.sort((a, b) => {
  if (b.score !== a.score) return b.score - a.score;
  return b.pubDate - a.pubDate;
});

// ============================================================
// 8. 중복 제거 및 TOP 5 선정 (링크 + 제목 기준)
// ============================================================
const uniqueTop5 = [];
const seenLinks = new Set();
const seenTitles = new Set();

for (const item of sortedArticles) {
  const link = item.article.json.link || item.article.json.guid || item.article.json.url || '';
  const titleKey = (item.title || '').toLowerCase();

  const isDupByLink = !!link && seenLinks.has(link);
  const isDupByTitle = !!titleKey && seenTitles.has(titleKey);

  if (!isDupByLink && !isDupByTitle) {
    uniqueTop5.push(item);
    if (link) seenLinks.add(link);
    if (titleKey) seenTitles.add(titleKey);
  }

  if (uniqueTop5.length >= 5) break;
}

const topArticles = uniqueTop5.map(item => item.article);
const articleUrls = topArticles.map(art =>
  art.json.link || art.json.guid || art.json.url || 'https://www.boannews.com'
);

console.log('\n🏆 선택된 TOP 5 기사:');
uniqueTop5.forEach((item, i) => {
  console.log(`\n${i + 1}. [${item.score}점] ${item.title || item.article.json.title}`);
  console.log(`   📅 ${item.pubDate.toLocaleString('ko-KR')}`);
  console.log(`   🔑 ${item.keywords.slice(0, 3).join(', ')}`);
});
console.log('\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n');

// ============================================================
// 9. LLM 입력 데이터 구성 (제목-only 금지)
// ============================================================
const groundedArticles = uniqueTop5.map((item, i) => ({
  id: i + 1,
  title: item.title || `제목없음-${i + 1}`,
  url: item.article.json.link || item.article.json.guid || item.article.json.url || '',
  published_at: isNaN(item.pubDate.getTime()) ? null : item.pubDate.toISOString(),
  source_text: item.sourceText
}));

// ============================================================
// 10. 프롬프트 (환각 억제: 원문 근거 강제)
// ============================================================
const systemPrompt = `역할: 당신은 20년차 정보보안 뉴스 요약 전문가다.

핵심 원칙:
1) 반드시 입력으로 주어진 source_text 안에서만 작성한다.
2) source_text에 없는 정보는 절대 쓰지 않는다.
3) 불확실하거나 근거가 없으면 "정보부족"이라고 쓴다.
4) 기사별 summary_bullets에는 추론/예측/산업 연결을 금지한다.
5) monthly_insights에서는 5개 기사 공통 패턴을 근거로 의료 환경 관점의 주의사항을 제한적으로 추론할 수 있다.
6) monthly_insights는 환자정보 보호, 진료 연속성, 의료기기/협력사 보안, 계정·접근통제 관점 중 최소 2개를 반드시 포함한다.
7) 각 문장은 한국어 평서문으로 작성한다.
8) 출력은 지정된 JSON 스키마만 따른다.`;

const userPrompt = `아래 5개 기사 데이터만 사용해 요약하라.
반드시 각 기사에 id와 title을 포함하라.
title은 입력 기사 JSON의 title 문자열을 한 글자도 바꾸지 말고 그대로 복사하라.
각 기사마다 summary_bullets는 정확히 3개로 작성하라.
각 bullet은 source_text의 사실을 재서술하고, 원문 근거 구절을 evidence_quotes에 짧게 넣어라.
근거를 찾지 못하면 해당 bullet은 "정보부족"으로 작성하고 evidence_quotes는 빈 배열로 둬라.
마지막에 monthly_insights는 정확히 3개 문장으로 작성하라.
monthly_insights는 의료 환경에서 실제 운영 시 주의해야 할 행동 중심 문장으로 작성하라.
monthly_insights에는 특정 기관명을 직접 쓰지 마라.
monthly_insights는 특정 고정 주어 표현으로 시작하지 마라.

입력 기사 JSON:
${JSON.stringify(groundedArticles, null, 2)}`;

// Structured output schema (Context7 근거: strict + additionalProperties:false)
const summarySchema = {
  type: 'json_schema',
  json_schema: {
    name: 'security_news_grounded_summary',
    strict: true,
    schema: {
      type: 'object',
      additionalProperties: false,
      required: ['articles', 'monthly_insights'],
      properties: {
        articles: {
          type: 'array',
          minItems: groundedArticles.length,
          maxItems: groundedArticles.length,
          items: {
            type: 'object',
            additionalProperties: false,
            required: ['id', 'title', 'summary_bullets', 'evidence_quotes'],
            properties: {
              id: { type: 'integer' },
              title: { type: 'string' },
              summary_bullets: {
                type: 'array',
                minItems: 3,
                maxItems: 3,
                items: { type: 'string' }
              },
              evidence_quotes: {
                type: 'array',
                minItems: 3,
                maxItems: 3,
                items: {
                  type: 'array',
                  items: { type: 'string' }
                }
              }
            }
          }
        },
        monthly_insights: {
          type: 'array',
          minItems: 3,
          maxItems: 3,
          items: { type: 'string' }
        }
      }
    }
  }
};

const payload = {
  model: 'exaone',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  temperature: 0,
  top_p: 0.1,
  max_tokens: 3500,
  article_urls: articleUrls,
  article_titles: groundedArticles.map((a) => a.title),
  article_title_map: Object.fromEntries(groundedArticles.map((a) => [String(a.id), a.title])),
  metadata: {
    total_articles: rssArticles.length,
    filtered_count: filteredArticles.length,
    excluded_count: rssArticles.length - filteredArticles.length,
    top5_scores: uniqueTop5.map(item => item.score),
    grounded_input_chars: groundedArticles.map(a => a.source_text.length),
    generated_at: new Date().toISOString(),
    version: '5.2-grounded-json'
  }
};

if (USE_JSON_SCHEMA) {
  payload.response_format = summarySchema;
}

return [{ json: payload }];

const now = new Date();
const year = now.getFullYear();
const month = now.getMonth() + 1;

const httpResponse = $input.first();
if (!httpResponse || !httpResponse.json) {
  throw new Error('HTTP Request 응답 없음');
}

const aiResponse = httpResponse.json;

function escapeHtml(input) {
  return String(input || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function stripCodeFence(value) {
  return String(value || '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```\s*$/i, '')
    .trim();
}

function safeJsonParse(value) {
  if (typeof value !== 'string') return null;
  const stripped = stripCodeFence(value);
  if (!stripped) return null;

  try {
    return JSON.parse(stripped);
  } catch (_) {
    return null;
  }
}

function tryParseJsonFragments(value) {
  if (typeof value !== 'string') return null;
  const text = stripCodeFence(value);
  if (!text) return null;

  const direct = safeJsonParse(text);
  if (direct) return direct;

  // 문자열 내부 JSON 블록을 브레이스 매칭으로 추출
  for (let i = 0; i < text.length; i++) {
    if (text[i] !== '{') continue;

    let depth = 0;
    let inString = false;
    let escape = false;

    for (let j = i; j < text.length; j++) {
      const ch = text[j];

      if (inString) {
        if (escape) {
          escape = false;
        } else if (ch === '\\') {
          escape = true;
        } else if (ch === '"') {
          inString = false;
        }
      } else {
        if (ch === '"') {
          inString = true;
        } else if (ch === '{') {
          depth += 1;
        } else if (ch === '}') {
          depth -= 1;
          if (depth === 0) {
            const candidate = text.slice(i, j + 1);
            const parsed = safeJsonParse(candidate);
            if (parsed) return parsed;
            break;
          }
        }
      }
    }
  }

  return null;
}

function deepFindStructuredObject(node, depth = 0, maxDepth = 10) {
  if (!node || depth > maxDepth) return null;

  if (typeof node === 'object' && !Array.isArray(node)) {
    if (Array.isArray(node.articles)) {
      return node;
    }

    for (const key of Object.keys(node)) {
      const found = deepFindStructuredObject(node[key], depth + 1, maxDepth);
      if (found) return found;
    }
  }

  if (Array.isArray(node)) {
    for (const item of node) {
      const found = deepFindStructuredObject(item, depth + 1, maxDepth);
      if (found) return found;
    }
  }

  return null;
}

function collectStringCandidates(node, out = [], depth = 0, maxDepth = 10) {
  if (depth > maxDepth || node == null) return out;

  if (typeof node === 'string') {
    const t = node.trim();
    if (t) out.push(t);
    return out;
  }

  if (Array.isArray(node)) {
    for (const item of node) {
      collectStringCandidates(item, out, depth + 1, maxDepth);
    }
    return out;
  }

  if (typeof node === 'object') {
    for (const key of Object.keys(node)) {
      const value = node[key];
      if (typeof value === 'string') {
        const t = value.trim();
        if (t) out.push(t);
      } else {
        collectStringCandidates(value, out, depth + 1, maxDepth);
      }
    }
  }

  return out;
}

function extractTextFromKnownShapes(response) {
  const texts = [];

  const message = response?.choices?.[0]?.message;
  if (message) {
    if (typeof message.content === 'string') {
      texts.push(message.content);
    }
    if (Array.isArray(message.content)) {
      for (const part of message.content) {
        if (typeof part === 'string') texts.push(part);
        if (part && typeof part.text === 'string') texts.push(part.text);
        if (part && typeof part.content === 'string') texts.push(part.content);
      }
    }
  }

  // Responses API: output[].content[].text
  if (Array.isArray(response?.output)) {
    for (const item of response.output) {
      if (typeof item?.output_text === 'string') {
        texts.push(item.output_text);
      }
      if (Array.isArray(item?.content)) {
        for (const c of item.content) {
          if (typeof c?.text === 'string') texts.push(c.text);
        }
      }
    }
  }

  if (typeof response?.output_text === 'string') texts.push(response.output_text);
  if (typeof response?.response === 'string') texts.push(response.response);
  if (typeof response?.text === 'string') texts.push(response.text);
  if (typeof response?.result === 'string') texts.push(response.result);

  return texts.filter(Boolean);
}

function normalizeStructuredShape(candidate) {
  if (!candidate || typeof candidate !== 'object') return null;

  // 모델이 루트 배열로 반환하는 케이스 지원
  if (Array.isArray(candidate)) {
    candidate = { articles: candidate };
  }

  // 래핑된 형태 지원
  if (!Array.isArray(candidate.articles) && Array.isArray(candidate.data)) {
    candidate = { ...candidate, articles: candidate.data };
  }

  // articles 구조가 문자열일 경우 재시도
  if (typeof candidate.articles === 'string') {
    const reparsed = tryParseJsonFragments(candidate.articles);
    if (reparsed && Array.isArray(reparsed.articles)) {
      return normalizeStructuredShape(reparsed);
    }
  }

  if (!Array.isArray(candidate.articles)) return null;

  let insights = [];
  if (Array.isArray(candidate.monthly_insights)) {
    insights = candidate.monthly_insights;
  } else if (Array.isArray(candidate.insights)) {
    insights = candidate.insights;
  } else if (typeof candidate.monthly_insights === 'string') {
    insights = candidate.monthly_insights
      .split('\n')
      .map(v => v.replace(/^[-•]\s*/, '').trim())
      .filter(Boolean);
  }

  const articles = candidate.articles.map((a, idx) => {
    const title = String(a?.title || a?.article_title || `기사 ${idx + 1}`).trim();

    let bullets = [];
    if (Array.isArray(a?.summary_bullets)) {
      bullets = a.summary_bullets;
    } else if (Array.isArray(a?.bullets)) {
      bullets = a.bullets;
    } else if (typeof a?.summary === 'string') {
      bullets = a.summary.split(/\n|•|-/).map(s => s.trim()).filter(Boolean);
    }

    const normalizedBullets = bullets
      .map((v) => {
        if (typeof v === 'string') return v;
        if (v && typeof v === 'object') {
          if (typeof v.text === 'string') return v.text;
          if (typeof v.summary === 'string') return v.summary;
          if (typeof v.bullet === 'string') return v.bullet;
        }
        return '';
      })
      .map(v => String(v || '').trim())
      .filter(Boolean);

    return {
      id: Number(a?.id || idx + 1),
      title,
      summary_bullets: normalizedBullets
    };
  });

  return {
    articles,
    monthly_insights: insights.map(v => String(v || '').trim()).filter(Boolean)
  };
}

function normalizeFromParsedValue(parsed) {
  if (typeof parsed === 'string') {
    const reparsed = tryParseJsonFragments(parsed);
    return normalizeStructuredShape(reparsed);
  }
  return normalizeStructuredShape(parsed);
}

function getStructuredPayload(response) {
  // 1) 객체 내 직접 탐색
  const direct = deepFindStructuredObject(response);
  const normalizedDirect = normalizeStructuredShape(direct);
  if (normalizedDirect) return normalizedDirect;

  // 2) SDK parse 경로
  const parsedMessage = response?.choices?.[0]?.message?.parsed;
  const normalizedParsedMessage = normalizeStructuredShape(parsedMessage);
  if (normalizedParsedMessage) return normalizedParsedMessage;

  // 3) 알려진 텍스트 필드에서 JSON 파싱
  const knownTexts = extractTextFromKnownShapes(response);
  for (const text of knownTexts) {
    const parsed = tryParseJsonFragments(text);
    const normalized = normalizeFromParsedValue(parsed);
    if (normalized) return normalized;
  }

  // 4) 전체 객체에서 문자열 수집 후 JSON 파싱
  const allStrings = collectStringCandidates(response, []);
  for (const text of allStrings) {
    const parsed = tryParseJsonFragments(text);
    const normalized = normalizeFromParsedValue(parsed);
    if (normalized) return normalized;
  }

  return null;
}

function getBestPlainText(response) {
  const candidates = [];
  candidates.push(...extractTextFromKnownShapes(response));
  candidates.push(...collectStringCandidates(response, []));

  const unique = [...new Set(candidates.map(v => String(v || '').trim()).filter(Boolean))];
  unique.sort((a, b) => b.length - a.length);
  return unique[0] || '';
}

