    { label: '진료서비스 연속성', keys: ['공격', '해킹', '침해', 'ddos', '디도스', '랜섬웨어', '악성코드'] },
    { label: '취약점·패치 관리', keys: ['취약점', 'cve', '패치', '업데이트'] },
    { label: '사고 대응체계·보고', keys: ['대응', '조치', '통보', '개편', '본부', '강화'] },
