    { label: '협력사·공급망 보안', keys: ['공급망', '협력사', '외주', 'third party', 'supply'] }
  ];

  const ranked = themes
    .map((t) => ({
      label: t.label,
      score: t.keys.reduce((acc, k) => acc + (fullText.includes(k) ? 1 : 0), 0)
    }))
    .filter((t) => t.score > 0)
    .sort((a, b) => b.score - a.score);

  const topThemes = ranked.slice(0, 3).map((r) => r.label);
  const insights = [];

  if (topThemes.length > 0) {
    insights.push(`${topThemes.join(', ')} 이슈가 반복된 점을 반영해 동일 유형 시스템의 점검 주기를 단축해야 한다.`);
  }

  insights.push('진료 중단으로 이어질 수 있는 공격 시나리오를 기준으로 비상운영 절차와 복구 우선순위를 사전에 점검해야 한다.');
  insights.push('환자정보 접근 계정과 외부 연계 계정을 분리 관리하고, 이상 로그인과 권한 오남용 모니터링을 상시 강화해야 한다.');

  return insights.slice(0, 3);
}

function isMedicalContextInsight(insight) {
  const t = String(insight || '').toLowerCase();
  const medicalKeywords = ['의료', '환자', '진료', '처방', '의무기록', 'emr', 'pacs', '검사', '원무'];
  return medicalKeywords.some((k) => t.includes(k));
}

function buildMedicalInsights(modelInsights, articles) {
  const base = Array.isArray(modelInsights)
    ? modelInsights.map((v) => String(v || '').trim()).filter(Boolean)
    : [];

  const sanitizedBase = base.map((line) =>
    line
      .replace(/의료서비스\s*운영\s*조직은\s*/g, '')
      .replace(/의료서비스\s*운영\s*조직이\s*/g, '')
      .trim()
  );

  const medicalCount = sanitizedBase.filter(isMedicalContextInsight).length;
  if (sanitizedBase.length >= 3 && medicalCount >= 2) {
    return sanitizedBase.slice(0, 3);
  }

  return buildFallbackInsightsFromArticles(articles);
}

