    const article = structured.articles[i] || {};
    const articleId = Number(article.id);
    const mappedTitle = Number.isInteger(articleId) && articleId > 0
      ? (articleTitleMap[String(articleId)] || articleTitles[articleId - 1] || '')
      : '';
    const modelTitle = String(article.title || '').trim();
    const genericTitle = /^(기사\s*\d+|article\s*\d+)$/i.test(modelTitle);
    const title = (!genericTitle && modelTitle) || mappedTitle || articleTitles[i] || `기사 ${i + 1}`;
