  let newsCount = 0;
  let currentTitle = '';
  let currentSummary = '';
  let inInsight = false;
  const insightItems = [];
  const parsedArticles = [];

  function flushArticle() {
    if (!currentTitle) return;

    const bullets = currentSummary
      .split(/\n|•|\s-\s|\r\n/)
      .map(s => s.trim())
      .filter(Boolean);

    const url = articleUrls[newsCount - 1] || 'https://www.dailysecu.com';
    html += renderArticleCard(newsCount, currentTitle, bullets, url);
    renderedArticleCount += 1;
    parsedArticles.push({ summary_bullets: bullets });

    currentTitle = '';
    currentSummary = '';
  }

  for (const raw of lines) {
    const line = String(raw || '').trim();
    if (!line) continue;

    if (line.includes('📌') || line.toLowerCase().includes('시사점')) {
      flushArticle();
      inInsight = true;
      continue;
    }

    if (inInsight) {
      if (line.startsWith('-') || line.startsWith('•')) {
        insightItems.push(line.replace(/^[-•]\s*/, ''));
      }
      continue;
    }

    if (/^(\d+[.)]\s*|기사\s*\d+\s*[:.]\s*)/.test(line)) {
